import Foundation
import CryptoKit

// The models (2.4 GB) do not ship in the app: they are downloaded on first use, on Wi-Fi and before a blackout.
// What to download, from where, its size and SHA-256 checksum are in Contenido/datos/modelos.json
// (generated by app/exportar_datos.py from the files in app/Modelos).

struct RemoteModel: Codable, Identifiable {
    let id: String        // "generador" or "vectores"
    let name: String    // on-screen text
    let fileName: String
    let url: String
    let bytes: Int64
    let sha256: String

    enum CodingKeys: String, CodingKey {   // modelos.json keeps its Spanish keys
        case id, name = "nombre", fileName = "archivo", url, bytes, sha256
    }
}

enum DownloadError: LocalizedError {
    case missingList, insufficientSpace(Int64), http(Int), checksum(String)

    var errorDescription: String? {
        switch self {
        case .missingList: return "Falta la lista de modelos (modelos.json)."
        case .insufficientSpace(let missing): return "No hay espacio suficiente: libera \(Models.sizeText(missing)) e inténtalo de nuevo."
        case .http(let c): return "El servidor respondió con el código \(c). Comprueba la conexión e inténtalo de nuevo."
        case .checksum(let n): return "El archivo de \(n) ha llegado dañado. Vuelve a descargarlo."
        }
    }
}

enum Models {
    static func list() -> [RemoteModel] {
        let u = Resources.data.appendingPathComponent("modelos.json")
        guard let d = try? Data(contentsOf: u) else { return [] }
        return (try? JSONDecoder().decode([RemoteModel].self, from: d)) ?? []
    }

    /// Application Support/Modelos, excluded from iCloud backup (2.4 GB that can be downloaded again).
    static var folder: URL {
        let base = FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask)[0]
        var u = base.appendingPathComponent("Modelos", isDirectory: true)
        try? FileManager.default.createDirectory(at: u, withIntermediateDirectories: true)
        var v = URLResourceValues()
        v.isExcludedFromBackup = true
        try? u.setResourceValues(v)
        return u
    }

    private static func marker(_ m: RemoteModel) -> URL { folder.appendingPathComponent(m.fileName + ".ok") }

    /// Where the model is: 1) downloaded and verified; 2) only when launched from Xcode, the Mac's app/Modelos folder.
    static func path(_ m: RemoteModel) -> URL? {
        let fm = FileManager.default
        let d = folder.appendingPathComponent(m.fileName)
        if fm.fileExists(atPath: d.path) && fm.fileExists(atPath: marker(m).path) { return d }
        if let dev = ProcessInfo.processInfo.environment["APAGON_MODELOS"] {
            let p = URL(fileURLWithPath: dev).appendingPathComponent(m.fileName)
            if fm.isReadableFile(atPath: p.path) { return p }
        }
        return nil
    }

    static func pending() -> [RemoteModel] { list().filter { path($0) == nil } }

    static func freeSpace() -> Int64 {
        let v = try? folder.resourceValues(forKeys: [.volumeAvailableCapacityForImportantUsageKey])
        return v?.volumeAvailableCapacityForImportantUsage ?? Int64.max
    }

    static func sizeText(_ bytes: Int64) -> String {
        ByteCountFormatter.string(fromByteCount: bytes, countStyle: .file)
    }

    static func sha256(_ url: URL) throws -> String {
        let h = try FileHandle(forReadingFrom: url)
        defer { try? h.close() }
        var hasher = SHA256()
        while let d = try h.read(upToCount: 8 << 20), !d.isEmpty { hasher.update(data: d) }
        return hasher.finalize().map { String(format: "%02x", $0) }.joined()
    }

    /// Moves the downloaded file into place, checks its checksum and leaves the “verified” marker.
    static func install(_ m: RemoteModel, from temporaryFile: URL) throws {
        let destination = folder.appendingPathComponent(m.fileName)
        try? FileManager.default.removeItem(at: destination)
        try FileManager.default.moveItem(at: temporaryFile, to: destination)
        guard try sha256(destination) == m.sha256 else {
            try? FileManager.default.removeItem(at: destination)
            throw DownloadError.checksum(m.name)
        }
        try Data().write(to: marker(m))
    }

    /// To test the download again (Ajustes → Desarrollador).
    static func delete() {
        for m in list() {
            try? FileManager.default.removeItem(at: folder.appendingPathComponent(m.fileName))
            try? FileManager.default.removeItem(at: marker(m))
        }
    }
}

/// A download with progress that can resume if interrupted.
final class Download: NSObject, URLSessionDownloadDelegate {
    private var continuation: CheckedContinuation<URL, Error>?
    private let onProgress: (Int64, Int64) -> Void
    private var lastUpdate = Date.distantPast
    private(set) var pendingResumeData: Data?
    private lazy var session = URLSession(configuration: .default, delegate: self, delegateQueue: nil)

    init(onProgress: @escaping (Int64, Int64) -> Void) {
        self.onProgress = onProgress
    }

    /// Returns the path of our own temporary file with the download.
    func run(_ url: URL, resumeData: Data? = nil) async throws -> URL {
        defer { session.finishTasksAndInvalidate() }
        return try await withCheckedThrowingContinuation { (c: CheckedContinuation<URL, Error>) in
            continuation = c
            let task = resumeData.map { session.downloadTask(withResumeData: $0) } ?? session.downloadTask(with: url)
            task.resume()
        }
    }

    func urlSession(_ session: URLSession, downloadTask: URLSessionDownloadTask, didWriteData bytesWritten: Int64,
                    totalBytesWritten: Int64, totalBytesExpectedToWrite: Int64) {
        guard Date().timeIntervalSince(lastUpdate) > 0.25 else { return }
        lastUpdate = Date()
        onProgress(totalBytesWritten, totalBytesExpectedToWrite)
    }

    func urlSession(_ session: URLSession, downloadTask: URLSessionDownloadTask, didFinishDownloadingTo location: URL) {
        if let r = downloadTask.response as? HTTPURLResponse, !(200...299).contains(r.statusCode) {
            continuation?.resume(throwing: DownloadError.http(r.statusCode))
            continuation = nil
            return
        }
        // the temporary file is deleted when this method returns: it must be moved now
        let localCopy = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString + ".gguf")
        do {
            try FileManager.default.moveItem(at: location, to: localCopy)
            continuation?.resume(returning: localCopy)
        } catch {
            continuation?.resume(throwing: error)
        }
        continuation = nil
    }

    func urlSession(_ session: URLSession, task: URLSessionTask, didCompleteWithError error: Error?) {
        guard let error else { return }
        pendingResumeData = (error as NSError).userInfo[NSURLSessionDownloadTaskResumeData] as? Data
        continuation?.resume(throwing: error)
        continuation = nil
    }
}
